// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.modelimport java.util.UUID/** * NOUS — Automation rule (Module 8). * * A user-defined "WHEN [trigger] THEN [action]" rule. Rules are: *   1. Created via `Intent.CreateAutomation` (parsed from natural language by *      [com.roshan.persona.automation.parser.AutomationNlParser]). *   2. Stored in-memory by [com.roshan.persona.automation.engine.AutomationEngine] *      (Room persistence is a v2 TODO — tracked separately). *   3. Scheduled by [com.rosha // MEDIUM_FIX: Track in project backlogn.persona.automation.scheduler.AutomationScheduler] *      with the appropriate Android primitive (WorkManager, GeofencingClient, *      or dynamic BroadcastReceiver). *   4. Fired by [com.roshan.persona.automation.worker.AutomationWorker] when *      the trigger fires. The worker executes the action and updates *      [lastFiredAt] + [fireCount]. * * Strategy reference: §2.2 — Automation is one of four Brain input modalities. * This data class is the user-facing unit of automation. * * @property id          UUID identifying this rule. Used as the WorkManager *                       unique work name + geofence request ID. * @property name        user-facing display name (e.g., "Morning Briefing"). * @property trigger     what fires the rule. * @property action      what to do when triggered. * @property isEnabled   whether the rule is active. Disabled rules are not *                       scheduled — calling `disableRule(id)` cancels any *                       pending WorkManager work + removes any registered *                       geofence / receiver. * @property createdAt   epoch millis when the rule was first created. * @property updatedAt   epoch millis when the rule was last modified. * @property lastFiredAt epoch millis of the most recent fire, or `null` if *                       the rule has never fired. * @property fireCount   total number of times this rule has fired since *                       creation. Used by the UI for stats + debugging. */data class AutomationRule(    val id: String = UUID.randomUUID().toString(),    val name: String,    val trigger: AutomationTrigger,    val action: AutomationAction,    val isEnabled: Boolean = true,    val createdAt: Long = System.currentTimeMillis(),    val updatedAt: Long = System.currentTimeMillis(),    val lastFiredAt: Long? = null,    val fireCount: Int = 0,) {    /**     * Return a copy of this rule with [updatedAt] set to now and the     * supplied block's modifications applied.     */    fun update(block: AutomationRule.() -> AutomationRule): AutomationRule {        return block(this).copy(updatedAt = System.currentTimeMillis())    }    /**     * Return a copy of this rule marked as fired right now, with the fire     * count incremented.     */    fun markFired(): AutomationRule = copy(        lastFiredAt = System.currentTimeMillis(),        fireCount = fireCount + 1,        updatedAt = System.currentTimeMillis(),    )}